package kz.synapse.factory;import kz.synapse.database.Database;import kz.synapse.enums.*;import kz.synapse.models.*;public class UserFactory {    public static Student createStudent(String id, String name,                                        String email, String password,                                        Language language, School school,                                        int yearOfStudy) {        Student student = new Student(id, name, email, password,                language, school, yearOfStudy);        Database.getInstance().addUser(student);        return student;    }    public static Student createStudent(String id, String name,                                        String email, String password,                                        Language language, School school) {        return createStudent(id, name, email, password, language, school, 1);    }    public static ResearcherDecorator<GraduateStudent> createGraduateStudent(            String id, String name, String email, String password,            Language language, School school, GraduateDegree degree) {        GraduateStudent gs = new GraduateStudent(                id, name, email, password, language, school, degree);        Database.getInstance().addUser(gs);        ResearcherDecorator<GraduateStudent> decorator =                new ResearcherDecorator<>(gs);        Database.getInstance().addResearcher(decorator);        return decorator;    }    public static Teacher createTeacher(String id, String name,                                        String email, String password,                                        Language language,                                        TeacherPosition position, School school) {        if (position == TeacherPosition.PROFESSOR) {            return createProfessor(id, name, email, password,                    language, school).getInnerUser();        }        Teacher teacher = new Teacher(                id, name, email, password, language, position, school);        Database.getInstance().addUser(teacher);        return teacher;    }    public static ResearcherDecorator<Teacher> createProfessor(            String id, String name, String email, String password,            Language language, School school) {        Teacher professor = new Teacher(                id, name, email, password, language,                TeacherPosition.PROFESSOR, school);        Database.getInstance().addUser(professor);        ResearcherDecorator<Teacher> decorator =                new ResearcherDecorator<>(professor);        Database.getInstance().addResearcher(decorator);        return decorator;    }    @SuppressWarnings("unchecked")    public static <T extends User> ResearcherDecorator<T> wrapAsResearcher(T user) {        ResearcherDecorator<?> existing =                Database.getInstance().getResearcherFor(user);        if (existing != null) {            return (ResearcherDecorator<T>) existing;        }        ResearcherDecorator<T> decorator = new ResearcherDecorator<>(user);        Database.getInstance().addResearcher(decorator);        return decorator;    }    public static Admin createAdmin(String id, String name,                                    String email, String password,                                    Language language) {        Admin admin = new Admin(id, name, email, password, language);        Database.getInstance().addUser(admin);        return admin;    }    public static SchoolManager createSchoolManager(String id, String name,                                                    String email, String password,                                                    Language language,                                                    School school) {        SchoolManager manager = new SchoolManager(                id, name, email, password, language, school);        Database.getInstance().addUser(manager);        return manager;    }    public static ORManager createORManager(String id, String name,                                            String email, String password,                                            Language language) {        ORManager manager = new ORManager(                id, name, email, password, language);        Database.getInstance().addUser(manager);        return manager;    }    public static Dean createDean(String id, String name,                                  String email, String password,                                  Language language,                                  School school) {        Dean dean = new Dean(id, name, email, password, language, school);        Database.getInstance().addUser(dean);        return dean;    }    public static TechSupportSpecialist createTechSupport(String id, String name,                                                          String email, String password,                                                          Language language) {        TechSupportSpecialist ts = new TechSupportSpecialist(                id, name, email, password, language);        Database.getInstance().addUser(ts);        return ts;    }    public static ResearchCoordinator createResearchCoordinator(String id, String name,                                                                String email, String password,                                                                Language language) {        ResearchCoordinator rc = new ResearchCoordinator(                id, name, email, password, language);        Database.getInstance().addUser(rc);        return rc;    }}